package org.apache.accumulo.test.ample.metadata;

import static org.apache.accumulo.core.util.LazySingletons.RANDOM;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

import org.apache.accumulo.core.client.ConditionalWriter;
import org.apache.accumulo.core.client.ConditionalWriter.Result;
import org.apache.accumulo.core.client.ConditionalWriter.Status;
import org.apache.accumulo.core.data.ConditionalMutation;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A {@link ConditionalWriterInterceptor} that simulates the ambiguous outcomes that can occur when
 * performing conditional mutations. For each mutation one of the following three outcomes is chosen
 * at random:
 * <ul>
 * <li>The mutation is not written and a status of {@link Status#UNKNOWN} is returned.</li>
 * <li>The mutation is written but a status of {@link Status#UNKNOWN} is returned.</li>
 * <li>The mutation is written and the actual status is returned.</li>
 * </ul>
 * This exercises the code paths that must correctly handle {@link Status#UNKNOWN} results where the
 * outcome of the mutation may or may not have actually been applied.
 */
public class FlakyInterceptor implements ConditionalWriterInterceptor {

  private static final Logger log = LoggerFactory.getLogger(FlakyInterceptor.class);

  @Override
  public Iterator<Result> write(ConditionalWriter writer,
      Iterator<ConditionalMutation> mutations) {
    List<Result> results = new ArrayList<>();
    while (mutations.hasNext()) {
      results.add(write(writer, mutations.next()));
    }
    return results.iterator();
  }

  @Override
  public Result write(ConditionalWriter writer, ConditionalMutation mutation) {
    switch (RANDOM.get().nextInt(3)) {
      case 0:
        // Do not write and return UNKNOWN
        log.debug("Flaky conditional write: skipping write and returning UNKNOWN");
        return new Result(Status.UNKNOWN, mutation, null);
      case 1: {
        // Write and return UNKNOWN
        log.debug("Flaky conditional write: writing and returning UNKNOWN");
        Result result = writer.write(mutation);
        return new Result(Status.UNKNOWN, result.getMutation(), result.getTabletServer());
      }
      default:
        // Write and return the actual status
        log.debug("Flaky conditional write: writing and returning actual status");
        return writer.write(mutation);
    }
  }
}
