package org.apache.accumulo.test.ample.metadata;

import java.util.Map;

import org.apache.accumulo.core.conf.SiteConfiguration;
import org.apache.accumulo.core.metadata.AccumuloTable;
import org.apache.accumulo.core.metadata.schema.Ample;
import org.apache.accumulo.core.metadata.schema.Ample.DataLevel;
import org.apache.accumulo.server.ServerContext;

import com.google.common.base.Supplier;
import com.google.common.base.Suppliers;

/**
 * A test-only {@link ServerContext} that returns an {@link Ample} backed by {@link FlakyInterceptor}
 * so that conditional mutations performed against the metadata and root tables produce ambiguous
 * (i.e. {@link org.apache.accumulo.core.client.ConditionalWriter.Status#UNKNOWN}) outcomes. This is
 * useful for verifying that server processes correctly handle ambiguous conditional mutation
 * results.
 */
public class FlakyAmpleServerContext extends ServerContext {

  private final Supplier<Ample> ample = Suppliers.memoize(
      () -> TestAmple.create(this, Map.of(DataLevel.USER, AccumuloTable.METADATA.tableName(),
          DataLevel.METADATA, AccumuloTable.ROOT.tableName()), FlakyInterceptor::new));

  public FlakyAmpleServerContext(SiteConfiguration siteConfig) {
    super(siteConfig);
  }

  @Override
  public Ample getAmple() {
    return ample.get();
  }
}
