package org.apache.accumulo.test.ample;

import java.io.IOException;

import org.apache.accumulo.core.cli.ConfigOpts;
import org.apache.accumulo.manager.Manager;
import org.apache.accumulo.test.ample.metadata.FlakyAmpleServerContext;

/**
 * A {@link Manager} that uses a {@link FlakyAmpleServerContext} so that all conditional metadata
 * mutations it performs have ambiguous outcomes. Useful for testing that the Manager correctly
 * handles ambiguous conditional mutation results.
 */
public class FlakyAmpleManager extends Manager {

  protected FlakyAmpleManager(ConfigOpts opts, String[] args) throws IOException {
    super(opts, FlakyAmpleServerContext::new, args);
  }

  public static void main(String[] args) throws Exception {
    try (FlakyAmpleManager manager = new FlakyAmpleManager(new ConfigOpts(), args)) {
      manager.runServer();
    }
  }
}
